// RunTrialBalanceResponse 试算平衡响应
//
// 两项校验：
//
//	is_balanced      借贷平衡：∑period_debit == ∑period_credit
//	is_equation_valid 会计恒等式：资产期末余额 == 负债 + 所有者权益 + 收入 - 费用
type RunTrialBalanceResponse struct {
	Code         int32  `protobuf:"varint,1,opt,name=code" json:"code,omitempty"`
	Message      string `protobuf:"bytes,2,opt,name=message" json:"message,omitempty"`
	SnapshotDate string `protobuf:"bytes,3,opt,name=snapshot_date" json:"snapshot_date,omitempty"`

	// 按 (category, type) 分组的明细，已按类别+类型升序排列
	Summaries []*TrialBalanceCategorySummary `protobuf:"bytes,4,rep,name=summaries" json:"summaries,omitempty"`

	// 期间借贷合计（∑total_debit / ∑total_credit across all accounts）
	TotalDebit  string `protobuf:"bytes,5,opt,name=total_debit" json:"total_debit,omitempty"`
	TotalCredit string `protobuf:"bytes,6,opt,name=total_credit" json:"total_credit,omitempty"`

	// 借贷平衡校验
	IsBalanced bool   `protobuf:"varint,7,opt,name=is_balanced" json:"is_balanced,omitempty"`
	Imbalance  string `protobuf:"bytes,8,opt,name=imbalance" json:"imbalance,omitempty"` // TotalDebit - TotalCredit；平衡时为 "0"

	// 会计恒等式各科目期末余额汇总
	AssetEndingBalance     string `protobuf:"bytes,9,opt,name=asset_ending_balance" json:"asset_ending_balance,omitempty"`
	LiabilityEndingBalance string `protobuf:"bytes,10,opt,name=liability_ending_balance" json:"liability_ending_balance,omitempty"`
	EquityEndingBalance    string `protobuf:"bytes,11,opt,name=equity_ending_balance" json:"equity_ending_balance,omitempty"`
	RevenueEndingBalance   string `protobuf:"bytes,12,opt,name=revenue_ending_balance" json:"revenue_ending_balance,omitempty"`
	ExpenseEndingBalance   string `protobuf:"bytes,13,opt,name=expense_ending_balance" json:"expense_ending_balance,omitempty"`

	// 会计恒等式：资产 = 负债 + 所有者权益 + 收入 - 费用
	IsEquationValid bool   `protobuf:"varint,14,opt,name=is_equation_valid" json:"is_equation_valid,omitempty"`
	EquationDiff    string `protobuf:"bytes,15,opt,name=equation_diff" json:"equation_diff,omitempty"` // 资产 - (负债+权益+收入-费用)；成立时为 "0"
}

